require_once __DIR__.'/../includes/functions.php';require_role('admin');require_once __DIR__.'/../config/database.php';$counts=[];foreach(['users','job_roles','skills','projects','evidence_submissions','assessments','roadmaps'] as $table){$counts[$table]=(int)$pdo->query('SELECT COUNT(*) FROM `'.$table.'`')->fetchColumn();}$pending=(int)$pdo->query("SELECT COUNT(*) FROM evidence_submissions WHERE status IN ('pending','under_review','changes_requested')")->fetchColumn();$st=$pdo->query("SELECT e.evidence_id,e.title,e.status,e.submitted_at,u.full_name,s.skill_name FROM evidence_submissions e JOIN users u ON u.user_id=e.user_id JOIN skills s ON s.skill_id=e.skill_id ORDER BY e.submitted_at DESC LIMIT 8");$recent=$st->fetchAll();$pageTitle='Admin overview';$active='admin';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Platform administration</span><h1 class="h1">Admin overview</h1><p>Review platform activity and monitor the starter catalogue.</p></div><div class="row"><a class="btn btn-outline" href="<?=h(url('admin/users.php'))?>">Manage users</a><span class="pill pill-green">Administrator</span></div></div><div class="metric-grid"><?php foreach([['users','Users','♙'],['job_roles','Career roles','⌕'],['skills','Skills','◈'],['projects','Projects','◇'],['evidence_submissions','Evidence submissions','⌑'],['assessments','Assessments','◎'],['roadmaps','Roadmaps','↗'],['pending','Pending reviews','!']] as $item):$key=$item[0];?><div class="card stat-card"><div class="row-between"><span class="stat-label"><?=h($item[1])?></span><span class="stat-icon"><?=h($item[2])?></span></div><div class="stat-value"><?=number_format($key==='pending'?$pending:$counts[$key])?></div><div class="stat-note">Current database records</div></div><?php endforeach;?></div><section class="card card-pad" style="margin-top:20px"><div class="panel-title"><h3>Recent evidence activity</h3><a class="link-arrow" href="<?=h(url('mentor/dashboard.php'))?>">Open review queue →</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Submission</th><th>Student</th><th>Skill</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=h($r['title'])?></td><td><?=h($r['full_name'])?></td><td><?=h($r['skill_name'])?></td><td><span class="pill <?=$r['status']==='verified'?'pill-green':'pill-amber'?>"><?=h(ucwords(str_replace('_',' ',$r['status'])))?></span></td><td><?=date('d M Y',strtotime($r['submitted_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$recent):?><p class="muted small">No evidence submissions yet.</p><?php endif;?></section><div class="card card-pad" style="margin-top:20px"><h3 class="h3">Initial administrator setup</h3><p class="muted small">For a local college demonstration, register your own account first. Then run this one-time SQL statement in phpMyAdmin, replacing the email with your registered email address:</p><pre style="background:#f4f6fa;padding:14px;border-radius:10px;overflow:auto;font-size:12px">UPDATE users SET role = 'admin' WHERE email = 'your-email@example.com';</pre><p class="tiny muted">Sign out and sign back in after changing your role. Do not expose an administrator account or credentials on a public server.</p></div></div></main><?php include __DIR__.'/../includes/footer.php';?>
